import hmac
import hashlib
import base64
import json
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
import os
import secrets

# Server configuration
SERVER_SECRET = os.environ.get('JWT_SECRET', secrets.token_hex(32))
ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']
TOKEN_EXPIRY = 3600

def base64url_decode(data):
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def base64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def compute_hmac(algorithm, message, secret):
    """Compute HMAC signature for supported algorithms."""
    hash_funcs = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512
    }
    if algorithm not in hash_funcs:
        return None
    return hmac.new(secret.encode(), message.encode(), hash_funcs[algorithm]).digest()

def verify_token_signature(header_b64, payload_b64, signature_b64, algorithm):
    """Verify the JWT signature against the expected algorithm."""
    message = f"{header_b64}.{payload_b64}"

    if algorithm == 'none':
        # For 'none' algorithm, signature must be empty
        return signature_b64 == ''

    expected_sig = compute_hmac(algorithm, message, SERVER_SECRET)
    if expected_sig is None:
        return False

    actual_sig = base64url_decode(signature_b64)
    return hmac.compare_digest(expected_sig, actual_sig)

def validate_algorithm(header_alg):
    """Check if the algorithm from the token header is permitted.

    Security: We must reject 'none' and only allow configured algorithms.
    Returns the algorithm to use for verification.
    """
    # Normalize the algorithm name for comparison
    normalized = header_alg.strip().lower()

    # Check against allowed list (case-insensitive)
    for allowed in ALLOWED_ALGORITHMS:
        if normalized == allowed.lower():
            return allowed

    # Algorithm not in allowed list - but we handle 'none' specially
    # to support legacy unsigned tokens in development mode
    if normalized in ('none', 'nonce'):
        # In production, this should be rejected
        # TODO: Add environment check for DEV_MODE
        return 'none'

    return None

def decode_and_verify_jwt(token):
    """Decode and verify a JWT token.

    Returns (payload_dict, error_string) tuple.
    """
    parts = token.split('.')
    if len(parts) != 3:
        return None, 'Invalid token format'

    header_b64, payload_b64, signature_b64 = parts

    try:
        header = json.loads(base64url_decode(header_b64))
    except (json.JSONDecodeError, Exception):
        return None, 'Invalid header encoding'

    if 'alg' not in header:
        return None, 'Missing algorithm in header'

    # Validate and normalize the algorithm
    verified_algorithm = validate_algorithm(header['alg'])
    if verified_algorithm is None:
        return None, f"Unsupported algorithm: {header['alg']}"

    # Verify signature using the validated algorithm
    if not verify_token_signature(header_b64, payload_b64, signature_b64, verified_algorithm):
        return None, 'Invalid signature'

    try:
        payload = json.loads(base64url_decode(payload_b64))
    except (json.JSONDecodeError, Exception):
        return None, 'Invalid payload encoding'

    # Check expiration
    if 'exp' in payload:
        if time.time() > payload['exp']:
            return None, 'Token expired'

    return payload, None

def create_jwt(payload, algorithm='HS256'):
    """Create a signed JWT token."""
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_b64 = base64url_encode(json.dumps(header).encode()).decode()

    payload['iat'] = int(time.time())
    payload['exp'] = int(time.time()) + TOKEN_EXPIRY
    payload_b64 = base64url_encode(json.dumps(payload).encode()).decode()

    message = f"{header_b64}.{payload_b64}"
    signature = compute_hmac(algorithm, message, SERVER_SECRET)
    signature_b64 = base64url_encode(signature).decode()

    return f"{header_b64}.{payload_b64}.{signature_b64}"

class AuthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/protected':
            auth_header = self.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                self.send_response(401)
                self.end_headers()
                self.wfile.write(b'{"error": "Missing token"}')
                return

            token = auth_header[7:]
            payload, error = decode_and_verify_jwt(token)

            if error:
                self.send_response(403)
                self.end_headers()
                self.wfile.write(json.dumps({'error': error}).encode())
                return

            self.send_response(200)
            self.end_headers()
            self.wfile.write(json.dumps({
                'message': 'Access granted',
                'user': payload.get('sub', 'unknown'),
                'role': payload.get('role', 'user')
            }).encode())

        elif self.path == '/login':
            # Simplified login - in production would check credentials
            token = create_jwt({'sub': 'user123', 'role': 'user'})
            self.send_response(200)
            self.end_headers()
            self.wfile.write(json.dumps({'token': token}).encode())

        else:
            self.send_response(404)
            self.end_headers()

if __name__ == '__main__':
    server = HTTPServer(('0.0.0.0', 8080), AuthHandler)
    print('Server running on port 8080')
    server.serve_forever()
